<script setup lang="ts">
import { ref } from "vue";
import { secretsOf } from "../domain";
import { redactSecrets } from "../protocol/redact";
import { useSettingsStore } from "../stores/settings";
import { useSpeechStore } from "../stores/speech";
import AppIcon from "./AppIcon.vue";
const settings = useSettingsStore(); const speech = useSpeechStore();
const checking = ref(false); const error = ref(""); const status = ref(""); const showKey = ref(false);
async function refresh() { checking.value = true; error.value = ""; status.value = ""; try { const voices = await speech.refreshVoices(); if (!settings.settings.ttsVoice && voices[0]) await settings.patch({ ttsVoice: voices[0].voice }); status.value = `${voices.length} 个可用音色`; } catch (caught) { error.value = redactSecrets(caught instanceof Error ? caught.message : "音色列表读取失败", secretsOf(settings.settings)); } finally { checking.value = false; } }
</script>
<template>
  <div class="stack speech-settings">
    <div class="feature-heading"><span class="feature-icon"><AppIcon name="speaker" :size="27" /></span><div><h2>让 Agent 开口说话</h2><p>兼容桌面 VChat 的 SoVITS 与 MiMo 语音。</p></div></div>
    <div class="settings-group form-stack"><label class="field">语音服务<select v-model="settings.settings.ttsMode" @change="settings.patch({ ttsMode: settings.settings.ttsMode, ttsVoice: '' }); speech.voices = []"><option value="sovits">SoVITS · VChat 兼容</option><option value="mimo">MiMo · 网络语音</option></select></label><label class="field">服务地址<input v-model="settings.settings.ttsUrl" type="url" autocapitalize="none" :placeholder="settings.settings.ttsMode === 'sovits' ? 'http://你的服务器:8000' : 'https://服务地址/v1/chat/completions'" @change="settings.patch({ ttsUrl: settings.settings.ttsUrl })" /></label><p class="hint">使用手机也能访问的地址。SoVITS 填基础地址，MiMo 可填完整接口。</p><label class="field">API Key<input v-model="settings.settings.ttsKey" :type="showKey ? 'text' : 'password'" autocomplete="off" autocapitalize="none" :placeholder="settings.settings.ttsMode === 'sovits' ? '无鉴权的 SoVITS 可以留空' : 'MiMo API Key'" @change="settings.patch({ ttsKey: settings.settings.ttsKey })" /></label><label class="check"><input v-model="showKey" type="checkbox" />显示密钥</label><label v-if="settings.settings.ttsMode === 'mimo'" class="field">语音模型<input v-model="settings.settings.ttsModel" type="text" placeholder="mimo-v2.5-tts" @change="settings.patch({ ttsModel: settings.settings.ttsModel })" /></label></div>
    <div class="settings-group form-stack"><div class="spread"><h3>默认音色</h3><button class="text-button" type="button" :disabled="checking" @click="refresh"><AppIcon name="history" :size="16" />{{ checking ? '正在读取…' : '刷新音色' }}</button></div><label class="field">音色<input v-model="settings.settings.ttsVoice" type="text" list="voice-options" placeholder="刷新后选择，也可填写音色 ID" @change="settings.patch({ ttsVoice: settings.settings.ttsVoice })" /></label><datalist id="voice-options"><option v-for="voice in speech.voices" :key="voice.voice" :value="voice.voice">{{ voice.name }}</option></datalist><p v-if="status" class="success-note">{{ status }}</p><label v-if="settings.settings.ttsMode === 'sovits'" class="range-field"><span>语速<strong>{{ settings.settings.ttsSpeed.toFixed(1) }}×</strong></span><input v-model.number="settings.settings.ttsSpeed" type="range" min="0.5" max="2" step="0.1" aria-label="默认语速" @change="settings.patch({ ttsSpeed: settings.settings.ttsSpeed })" /></label><p v-if="settings.settings.ttsMode === 'mimo'" class="hint">MiMo 的语速与情绪请写在导演提示词中。</p><label v-if="settings.settings.ttsMode === 'mimo'" class="field">导演提示词<textarea v-model="settings.settings.ttsDirector" rows="3" placeholder="例如：轻声、自然地说，语速稍慢" @change="settings.patch({ ttsDirector: settings.settings.ttsDirector })" /></label><p class="hint">每个 Agent 也可以单独设置音色。</p><button class="primary" type="button" :disabled="!settings.settings.ttsUrl || speech.phase === 'loading'" @click="speech.read('preview', '你好，我在这里。今天想一起做些什么？')"><AppIcon name="play" :size="18" />试听这段声音</button></div><p v-if="error" class="error-line" role="alert">{{ error }}</p>
  </div>
</template>
